<div class="dash-head"><div><h1>Roles & permissions</h1><p class="sub">Access is enforced on the server. Reserved grant permissions do not create grant-management features.</p></div><?php if (app(\App\Services\AuthService::class)->isSuperAdmin()): ?><a class="btn btn-brand" href="<?= e(base_url('admin/roles/create')) ?>">Create role</a><?php endif; ?></div>
<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Role</th><th>Key</th><th>Members</th><th>Actions</th></tr></thead><tbody><?php foreach ($roles as $role): ?><tr><td><strong><?= e($role['label']) ?></strong><br><small><?= e((string)$role['description']) ?></small></td><td><code><?= e($role['name']) ?></code></td><td><?= e((string)$role['members']) ?></td><td><a href="<?= e(base_url('admin/roles/'.(int)$role['id'].'/edit')) ?>">View permissions<?= app(\App\Services\AuthService::class)->isSuperAdmin() && $role['name']!=='super_admin' ? ' / edit' : '' ?></a></td></tr><?php endforeach; ?></tbody></table></div></section>
